svg.aria-label:
Code example:
// swift-tools-version:6.0
import PackageDescription

let package = Package(
    name: "Xwift",
    products: [
        .library(name: "XwiftCore", targets: ["XwiftCore"]),
        .executable(name: "xwift-hello", targets: ["xwift-hello"]),
    ],
    targets: [
        .target(name: "XwiftCore"),
        .executableTarget(name: "xwift-hello", dependencies: ["XwiftCore"]),
        .testTarget(name: "XwiftCoreTests", dependencies: ["XwiftCore"]),
    ],
    swiftLanguageModes: [.v6]
)

